B.c2t=new A.Dp(B.l0,"Restricted safety, enforcement, dispute, and appeal records can remain after deletion only under the purpose-based retention, de-identification, and legal-hold rules described in the Privacy Policy. This build cannot ship until those rules are approved, implemented, and tested.",null)
B.amy=new A.ae(61355,"MaterialIcons",!1)
B.c2u=new A.Dp(B.amy,"Your sign-in account and account-owned profile, content, and service data will be permanently deleted. This cannot be undone.",null)
B.amv=new A.ae(61279,"MaterialIcons",!1)
B.c2v=new A.Dp(B.amv,"Stored-file cleanup may finish shortly afterward through a secure background cleanup job.",null)
B.c2w=new A.aqb(null)
B.c1=new A.Dr(0,"minWidth")
